import prettier from 'eslint-config-prettier';
import js from '@eslint/js';
import { includeIgnoreFile } from '@eslint/compat';
import svelte from 'eslint-plugin-svelte';
import globals from 'globals';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import ts from 'typescript-eslint';

const gitignorePath = fileURLToPath(new URL('./.gitignore', import.meta.url));

/**
 * Every file shipped by the registry (generated by `pnpm registry:build`).
 * jsrepo rewrites imports in these files to the consumer's alias (`$lib` in SvelteKit 2, `#lib` in SvelteKit 3)
 * and keeps the original extension, so the extension has to be valid in both.
 */
function getRegistryFiles() {
	try {
		const registry = JSON.parse(
			fs.readFileSync(new URL('./registry.json', import.meta.url), 'utf8')
		);
		return [...new Set(registry.items.flatMap((item) => item.files.map((file) => file.path)))];
	} catch {
		if (process.env.CI) {
			throw new Error('registry.json not found. Run `pnpm registry:build` before linting.');
		}
		console.warn(
			'registry.json not found, skipping registry import rules. Run `pnpm registry:build`.'
		);
		return [];
	}
}

const registryFiles = getRegistryFiles();

export default ts.config(
	includeIgnoreFile(gitignorePath),
	js.configs.recommended,
	...ts.configs.recommended,
	...svelte.configs['flat/recommended'],
	prettier,
	...svelte.configs['flat/prettier'],
	{
		languageOptions: {
			globals: {
				...globals.browser,
				...globals.node
			}
		},
		rules: {
			'@typescript-eslint/no-unused-vars': [
				'error',
				{
					varsIgnorePattern: '^_',
					argsIgnorePattern: '^_'
				}
			],
			'no-prototype-builtins': 'off',
			'no-useless-escape': 'off',
			'svelte/no-navigation-without-resolve': 'off'
		}
	},
	{
		files: ['**/*.svelte', '**/*.svelte.ts', '**/*.svelte.js'],

		languageOptions: {
			parserOptions: {
				// it just ain't worth it man
				// projectService: true,
				extraFileExtensions: ['.svelte'],
				parser: ts.parser
			}
		},
		rules: {
			'svelte/no-useless-mustaches': 'off'
		}
	},
	// Registry files must use explicit `.js` / `.svelte` extensions on relative and `#lib` imports.
	// - `.ts` breaks SvelteKit 2 projects without `allowImportingTsExtensions`
	// - no extension breaks SvelteKit 3 projects since `#lib/*` (package.json `imports`) needs the full file name
	...(registryFiles.length > 0
		? [
				{
					files: registryFiles,
					rules: {
						'no-restricted-imports': [
							'error',
							{
								patterns: [
									{
										regex: '^(?:\\.{1,2}(?:/.*)?|#lib/.*)(?<!\\.js)(?<!\\.svelte)$',
										message:
											"Registry files must import with an explicit `.js` or `.svelte` extension (use `.js` for `.ts` files, `./index.js` instead of `'.'`)."
									}
								]
							}
						]
					}
				}
			]
		: [])
);
